// index.js
const {helpers} = require('/home/node/node_modules/helpers_jsonld')



for (const item of $input.all()) {

  let i = JSON.parse(JSON.stringify(item.json))

  let c_record = i.action?.object || {}


  let c = new helpers.things.Conversation(c_record)



  // Add message
  c.addMessage(item.json.config?.message?.sender, item.json.config?.message?.recipient, item.json.config.message?.headline || "", item.json.config.message?.text || "", $now, $now)

  item.json.action.result = c





}

return $input.all();

